package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextProductionCapture.Clause;
final class ContextGeneralArgumentsMatrix {
 static int checks;static final int WORK=64000000;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static String atom(String name,List<String> args){return name+"("+String.join(",",args)+")";}
 static List<String> values(int n){List<String> a=new ArrayList<>();for(int i=0;i<n;i++)a.add(Integer.toString(i+1));return a;}
 static List<String> variables(int n){List<String> a=new ArrayList<>();for(int i=0;i<n;i++)a.add("v"+i);return a;}
 static String prefix(List<String> vars){StringBuilder s=new StringBuilder("!");for(String v:new LinkedHashSet<>(vars))if(v.startsWith("v"))s.append('@').append(v).append(' ');return s.toString();}
 static String rule(int n){List<String> vars=variables(n),back=new ArrayList<>(vars);Collections.reverse(back);return prefix(vars)+atom("wide",vars)+"->"+atom("out",back)+";";}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextSignedUnaryModelMatrix.bind(x,s);}
 static ContextSignedWitnessNativeBranch.Receipt run(Snapshot x,List<Snapshot> fs,boolean no){ContextSignedWitnessNativeBranch.Policy p=ContextSignedWitnessNativeMatrix.policy();ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(x,fs,p);require(r.status==(no?ContextSignedWitnessNativeBranch.Status.REFUTED:ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED),r.phase+": "+r.reason);ContextSignedWitnessNativeBranch.Receipt b=no?r.rejection:r.output;ContextSignedWitnessNativeBranchAudit.check(b,x,fs,p,WORK,64);require(true,"fresh full native proof/stop audit");return b;}
 static void shapes()throws Exception{
  for(int n:new int[]{0,1,4,9,17,64,257}){List<String> vars=variables(n);Snapshot all=bind(true,prefix(vars)+atom("wide",vars)+";");require(all.primary.get(0).clauses.get(0).literals.get(0).arguments.size()==n&&all.primary.get(0).clauses.get(0).variables.size()==n,"ALL variable positions and identities retained for arity="+n);Snapshot ground=bind(true,"!"+atom("wide",values(n))+";");require(ground.primary.get(0).clauses.get(0).variables.isEmpty()&&ground.primary.get(0).clauses.get(0).literals.get(0).arguments.size()==n,"ALL constants retained for arity="+n);}
  int n=17;List<String> args=values(n);args.set(0,"v0");args.set(n-1,"v0");Snapshot mixed=bind(true,prefix(args)+atom("wide",args)+";");Clause c=mixed.primary.get(0).clauses.get(0);require(c.variables.size()==1&&c.literals.get(0).arguments.get(0).variable==c.literals.get(0).arguments.get(n-1).variable,"repeated variable at opposite ends stays ONE identity amid constants");
  List<String> renamed=new ArrayList<>(args);renamed.set(0,"vrenamed");renamed.set(n-1,"vrenamed");Clause alpha=bind(true,prefix(renamed)+atom("wide",renamed)+";").primary.get(0).clauses.get(0);require(c.equivalent(alpha,ContextGroundProductionRounds.budget(WORK)),"alpha identity independent of spelling");renamed.set(n-1,"vother");Clause different=bind(true,prefix(renamed)+atom("wide",renamed)+";").primary.get(0).clauses.get(0);require(!c.equivalent(different,ContextGroundProductionRounds.budget(WORK)),"late repeated-variable mismatch cannot be ignored");
  boolean stopped=false;try{c.equivalent(alpha,ContextGroundProductionRounds.budget(4));}catch(IllegalStateException ex){stopped=true;}require(stopped,"wide alpha comparison charges argument positions, no prefix success");
  System.out.println("GENERAL_ARGUMENT_SHAPES arities=0,1,4,9,17,64,257 allConstants=true allVariables=true mixedAndRepeated=true budgetedAlpha=true");
 }
 static void inference()throws Exception{
  for(int n:new int[]{0,4,9,17,64}){Snapshot x=bind(true,rule(n));List<String> v=values(n),back=new ArrayList<>(v);Collections.reverse(back);Snapshot a=bind(false,"!"+atom("wide",v)+";"),b=bind(false,"!~"+atom("out",back)+";");ContextSignedWitnessNativeBranch.Receipt yes=run(x,Collections.singletonList(a),false);require(yes.termination.result.output.current().packet.items.stream().anyMatch(i->i.atom.predicate.equals("out")&&i.atom.arguments.size()==n&&i.proofs.stream().anyMatch(p->p.sources.size()==2)),"whole arbitrary-arity product, reversed positions and exact two Sources n="+n);for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessNativeBranch.Receipt no=run(x,reverse?Arrays.asList(b,a):Arrays.asList(a,b),true);require(ContextSignedBranchInspection.oppositions(no).stream().anyMatch(o->o.sources.size()==3),"whole tuple refutes with exactly three original Sources in both orders n="+n);}}
  // Witness seed/frame/transport must also retain a long tuple, not just universal clause metadata.
  List<String> args=values(17);args.set(0,"u");args.set(16,"u");Snapshot x=bind(true,"!@u "+atom("wide",args)+"->mark(u);"),a=bind(false,"!$u "+atom("wide",args)+";");ContextSignedWitnessNativeBranch.Receipt b=run(x,Collections.singletonList(a),false);require(b.termination.result.output.current().packet.items.stream().anyMatch(i->i.atom.predicate.equals("mark")&&i.proofs.stream().anyMatch(p->p.sources.size()==2)),"long witness seed retains Source-owned Origin and late repeated binder");
  System.out.println("GENERAL_ARGUMENT_INFERENCE arbitraryVariableCount=true reversedTuples=true bothOrders=true exactSources=true longWitnessSeed=true");
 }
 static void unification()throws Exception{
  int n=64;Snapshot x=bind(true,rule(n));Clause producer=x.primary.get(0).clauses.get(0);List<String> vals=values(n),back=new ArrayList<>(vals);Collections.reverse(back);Clause unit=bind(false,"!"+atom("wide",vals)+";").primary.get(0).clauses.get(0);int pivot=0;for(int i=0;i<producer.literals.size();i++)if(producer.literals.get(i).predicate.equals("wide"))pivot=i;Clause result=producer.resolveWithUnits(unit,pivot,0,ContextGroundProductionRounds.budget(WORK));Clause expected=bind(true,"!"+atom("out",back)+";").primary.get(0).clauses.get(0);require(result.equivalent(expected,ContextGroundProductionRounds.budget(WORK)),"64-variable MGU substitutes every reversed position");
  List<String> pattern=values(17);pattern.set(0,"v0");pattern.set(16,"v0");Clause repeated=bind(true,prefix(pattern)+atom("wide",pattern)+"->out(v0);").primary.get(0).clauses.get(0);List<String> wrong=values(17);Clause conflict=bind(false,"!"+atom("wide",wrong)+";").primary.get(0).clauses.get(0);int p=0;for(int i=0;i<repeated.literals.size();i++)if(repeated.literals.get(i).predicate.equals("wide"))p=i;boolean no=false;try{repeated.resolveWithUnits(conflict,p,0,ContextGroundProductionRounds.budget(WORK));}catch(Clause.UnificationFailure ex){no=true;}require(no,"late constant conflict in a repeated variable is real unification failure");wrong.set(16,"1");Clause good=bind(false,"!"+atom("wide",wrong)+";").primary.get(0).clauses.get(0);require(repeated.resolveWithUnits(good,p,0,ContextGroundProductionRounds.budget(WORK)).equivalent(bind(true,"!out(1);").primary.get(0).clauses.get(0)),"same repeated variable unifies when both endpoints agree");
  List<String> typed=values(17);typed.set(0,"v0");typed.set(16,"\"7\"");Clause typeRule=bind(true,prefix(typed)+atom("wide",typed)+"->out(v0);").primary.get(0).clauses.get(0);List<String> numeric=values(17);numeric.set(16,"7");Clause numericUnit=bind(false,"!"+atom("wide",numeric)+";").primary.get(0).clauses.get(0);p=0;for(int i=0;i<typeRule.literals.size();i++)if(typeRule.literals.get(i).predicate.equals("wide"))p=i;no=false;try{typeRule.resolveWithUnits(numericUnit,p,0,ContextGroundProductionRounds.budget(WORK));}catch(Clause.UnificationFailure ex){no=true;}require(no,"typed string7 and numeric7 in late position remain different");
  boolean stop=false;try{producer.resolveWithUnits(unit,pivot,0,ContextGroundProductionRounds.budget(16));}catch(IllegalStateException ex){stop=true;}require(stop,"wide MGU work exhausts before any result escapes");
  System.out.println("GENERAL_ARGUMENT_UNIFICATION everyPosition=true repeatedVariableConstraints=true typedLateConstant=true boundedNoPrefix=true");
 }
}
